	/**
	 * Default Constructor
	 */
    public CategoryService(CurrentIdentity identity,
				ApplicationContext applicationContext)  {

		this.identity		= identity;
		this.projector 		= new CategoryEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(CategoryRepository.class) );
		this.validator		= applicationContext.getBean(CategoryValidator.class) ;
	}


	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		Category
	 */
		public Category createCategory( CreateCategoryCommand command ) {

		Category entity = new Category();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setCategoryId( command.getCategoryId() );
            entity.setName( command.getName() );
            entity.setSlug( command.getSlug() );
            entity.setPosition( command.getPosition() );
            entity.setAsActive( command.getAsActive() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of Category {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdateCategoryCommand
	 * @return		Category
	 */
	public Category updateCategory( UpdateCategoryCommand command ) {

		Category entity = new Category();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setCategoryId( command.getCategoryId() );
            entity.setName( command.getName() );
            entity.setSlug( command.getSlug() );
            entity.setPosition( command.getPosition() );
            entity.setAsActive( command.getAsActive() );
            entity.setCatalog( command.getCatalog() );
            entity.setParentCategory( command.getParentCategory() );
            entity.setSubcategories( command.getSubcategories() );
            entity.setProducts( command.getProducts() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of Category {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Deletes the associatied value object
	 * @param		command DeleteCategoryCommand
	 */
	public void delete( DeleteCategoryCommand command ) {
		UUID id = null;

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		id = command.getCategoryId();

		// ------------------------------------------
		// delete the entity
		// ------------------------------------------
		projector.delete(id);

		LOGGER.info( "done deleting of Category {0} ", id );

	}

	/**
	 * Method to retrieve the Category via CategoryFetchOneSummary
	 * @param 	summary CategoryFetchOneSummary
	 * @return 	CategoryFetchOneResponse
	 */
	public Category getCategory( CategoryFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "CategoryFetchOneSummary arg cannot be null" );

		Category entity = null;
		UUID id = summary.getCategoryId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a Category using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all Categorys
	 *
	 * @return 	List<Category>
	 */
    public List<Category> getAllCategory() {
		List<Category> list = projector.findAll( new FindAllCategoryQuery() );
		return list;
	}

	/**
	 * assign Catalog on Category
	 * @param		command AssignCatalogToCategoryCommand
	 */
	public void assignCatalog( AssignCatalogToCategoryCommand command ) {
		// --------------------------------------
		// best to validate the command now
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.assignCatalog(command.getCategoryId(), command.getAssignment());

	}

